using System;
using System.Collections.Generic;
using UnityEngine;

/// <summary>
/// Baked cycle distance for every walk/run clip. Generated by
/// tools/locomotion-stride/bake_strides.py — not hand-tuned.
/// </summary>
public static class LocomotionStrideCatalog
{
    public const string LogTag = "[LocomotionStride]";
    public const string IndexResourcesPath = "Data/Animations/locomotion_strides";

    static readonly Dictionary<string, float> ByClip =
        new Dictionary<string, float>(StringComparer.OrdinalIgnoreCase);
    static readonly List<EntryDto> Entries = new List<EntryDto>();
    static readonly HashSet<string> Logged = new HashSet<string>();
    static bool _loaded;

    [Serializable]
    sealed class IndexDto
    {
        public EntryDto[] entries;
    }

    [Serializable]
    sealed class EntryDto
    {
        public string clip;
        public string path;
        public string gait;
        public float strideMeters;
    }

    public static bool TryGet(string clipName, out float strideMeters)
    {
        EnsureLoaded();
        strideMeters = 0f;
        if (string.IsNullOrEmpty(clipName))
            return false;
        return ByClip.TryGetValue(clipName, out strideMeters)
            && strideMeters >= LocomotionGait.MinStrideMeters;
    }

    /// <summary>
    /// Animator state names use a token (<c>run_bow</c>, <c>run_1HS</c>) whose
    /// case does not always match the clip file (<c>Bow</c>, <c>1hs</c>).
    /// Resolve the generated resources path for that body and gait.
    /// </summary>
    public static bool TryResolveResourcesPath(
        string handResourcesPath,
        string weaponToken,
        out string resourcesPath)
    {
        resourcesPath = null;
        EnsureLoaded();
        if (string.IsNullOrEmpty(handResourcesPath))
            return false;

        string expected = SwapHandToken(handResourcesPath, weaponToken);
        string expectedFile = FileName(expected);
        for (int i = 0; i < Entries.Count; i++)
        {
            EntryDto entry = Entries[i];
            if (entry == null || string.IsNullOrEmpty(entry.path))
                continue;
            if (!string.Equals(FileName(entry.path), expectedFile, StringComparison.OrdinalIgnoreCase))
                continue;
            resourcesPath = entry.path;
            return true;
        }

        return false;
    }

    public static void LogMissing(string subject, string gait, string clipName)
    {
        string key = (subject ?? "") + "|" + (gait ?? "") + "|" + (clipName ?? "");
        if (!Logged.Add(key))
            return;

        Debug.LogError(
            LogTag + " missing stride " + (string.IsNullOrEmpty(subject) ? "subject=unknown" : subject)
            + " gait=" + (string.IsNullOrEmpty(gait) ? "unknown" : gait)
            + " clip=\"" + (clipName ?? "") + "\""
            + " (no baked cycle distance; no default stride)");
    }

    public static void ClearForTests()
    {
        _loaded = false;
        ByClip.Clear();
        Entries.Clear();
        Logged.Clear();
    }

    static string SwapHandToken(string handResourcesPath, string token)
    {
        if (string.IsNullOrEmpty(token) || token.Equals("hand", StringComparison.OrdinalIgnoreCase))
            return handResourcesPath;
        int i = handResourcesPath.LastIndexOf("_Hand_", StringComparison.OrdinalIgnoreCase);
        if (i < 0)
            return handResourcesPath;
        return handResourcesPath.Substring(0, i) + "_" + token + handResourcesPath.Substring(i + 5);
    }

    static string FileName(string resourcesPath)
    {
        int slash = resourcesPath.LastIndexOf('/');
        return slash >= 0 ? resourcesPath.Substring(slash + 1) : resourcesPath;
    }

    static void EnsureLoaded()
    {
        if (_loaded)
            return;
        _loaded = true;
        ByClip.Clear();
        Entries.Clear();

        TextAsset asset = Resources.Load<TextAsset>(IndexResourcesPath);
        if (asset == null || string.IsNullOrEmpty(asset.text))
        {
            Debug.LogError(
                LogTag + " missing generated index Resources/" + IndexResourcesPath
                + ".json — rebake with tools/locomotion-stride/bake_strides.py");
            return;
        }

        IndexDto index;
        try
        {
            index = JsonUtility.FromJson<IndexDto>(asset.text);
        }
        catch (Exception ex)
        {
            Debug.LogError(LogTag + " failed to parse stride index: " + ex.Message);
            return;
        }

        if (index?.entries == null)
        {
            Debug.LogError(LogTag + " stride index has no entries");
            return;
        }

        for (int i = 0; i < index.entries.Length; i++)
        {
            EntryDto entry = index.entries[i];
            if (entry == null || string.IsNullOrEmpty(entry.clip))
                continue;
            if (entry.strideMeters < LocomotionGait.MinStrideMeters)
                continue;
            if (ByClip.TryGetValue(entry.clip, out float existing))
            {
                if (Mathf.Abs(existing - entry.strideMeters) > 0.0001f)
                {
                    Debug.LogError(
                        LogTag + " conflicting stride for clip=\"" + entry.clip
                        + "\" " + existing.ToString("F4") + " vs " + entry.strideMeters.ToString("F4"));
                    ByClip.Remove(entry.clip);
                }
                continue;
            }

            ByClip[entry.clip] = entry.strideMeters;
            Entries.Add(entry);
        }
    }
}
